"""Carga autocontida dos dados TSE de 2004–2024 para o MotherDuck."""

import csv
import hashlib
import json
import os
import shutil
import sys
import time
import urllib.request
import zipfile
from pathlib import Path

import duckdb

NORMALIZER_SOURCE = '#!/usr/bin/env python3\n"""Normaliza os arquivos TSE de 2004 a 2024 para COPY em stg_tse.\n\nO script não conecta ao banco. Gera CSVs temporários locais, preservando texto\ne sentinelas; a publicação ocorre pelos scripts SQL existentes.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport io\nimport json\nfrom functools import lru_cache\nfrom collections import defaultdict\nfrom datetime import datetime\nfrom pathlib import Path\nimport unicodedata\nimport zipfile\n\nYEARS = (2004, 2006, 2008, 2010, 2012, 2014, 2016, 2018, 2020, 2022, 2024)\nUFS = {"AC", "AL", "BA", "DF", "RO", "SP"}\nSOURCES = (\n    "consulta_cand", "consulta_cand_complementar", "votacao_candidato_munzona",\n    "bem_candidato", "votacao_partido_munzona",\n    "detalhe_votacao_munzona", "perfil_eleitorado",\n    "prestacao_de_contas_eleitorais_candidatos",\n)\n\nSTAGES = {\n    "candidatura": ["ano_eleicao", "cd_eleicao", "nr_turno", "cd_tipo_eleicao", "nm_tipo_eleicao", "sg_uf", "sg_ue", "nm_ue", "cd_cargo", "ds_cargo", "sq_candidato", "sq_candidato_tse", "nr_cpf_candidato", "nm_candidato", "nm_urna_candidato", "dt_nascimento", "ds_grau_instrucao", "ds_genero", "ds_cor_raca", "nr_partido", "sg_partido", "nm_partido", "ds_sit_tot_turno", "source_file", "nr_titulo_eleitoral_candidato", "nr_candidato"],\n    "candidatura_complementar": ["ano_eleicao", "cd_eleicao", "sq_candidato", "nr_turno", "nm_tipo_destinacao_votos", "source_file"],\n    "bem_candidato": ["ano_eleicao", "sq_candidato", "nr_ordem_bem_candidato", "ds_tipo_bem_candidato", "ds_bem_candidato", "vr_bem_candidato", "source_file"],\n    "votacao_candidato_munzona": ["ano_eleicao", "sg_uf", "cd_eleicao", "nr_turno", "cd_cargo", "cd_municipio_tse", "sq_candidato", "qt_votos_nominais", "source_file"],\n    "votacao_partido_munzona": ["ano_eleicao", "sg_uf", "cd_eleicao", "nr_turno", "cd_cargo", "cd_municipio_tse", "nr_partido", "sg_partido", "qt_votos_legenda", "qt_votos_nominais", "source_file"],\n    "detalhe_votacao_munzona": ["ano_eleicao", "sg_uf", "cd_eleicao", "nr_turno", "cd_cargo", "cd_municipio_tse", "nr_zona", "qt_aptos", "qt_comparecimento", "qt_abstencao", "source_file"],\n    "perfil_eleitorado_municipio": ["ano_eleicao", "sg_uf", "cd_municipio_tse", "nr_zona", "ds_faixa_etaria", "ds_genero", "ds_estado_civil", "ds_grau_instrucao", "qt_eleitores_perfil", "source_file"],\n    "municipio_correspondencia": ["cd_municipio_tse", "cd_municipio_ibge", "nm_municipio", "sg_uf", "source_file"],\n    "receita_candidato": ["ano_eleicao", "sq_candidato", "id_linha_origem", "ds_fonte_receita", "vr_receita", "tp_origem_recurso", "source_file"],\n    "despesa_candidato": ["ano_eleicao", "sq_candidato", "id_linha_origem", "ds_despesa", "ds_categoria_despesa", "vr_pago", "source_file"],\n    "cobertura_despesa_paga": ["ano_eleicao", "sq_candidato", "completo", "source_manifest"],\n    "comparecimento_zonas_esperadas": ["ano_eleicao", "cd_eleicao", "nr_turno", "cd_municipio_tse", "nr_zona", "source_manifest", "manifesto_verificado"],\n}\n\nALIASES = {\n    "cd_municipio_tse": "CD_MUNICIPIO",\n    "qt_abstencao": "QT_ABSTENCOES",\n    "qt_eleitores_perfil": "QT_ELEITORES",\n    "ds_grau_instrucao": "DS_GRAU_ESCOLARIDADE",\n    "qt_votos_legenda": "QT_TOTAL_VOTOS_LEG_VALIDOS",\n}\n\n\ndef sha256(path: Path) -> str:\n    h = hashlib.sha256()\n    with path.open("rb") as f:\n        for block in iter(lambda: f.read(1024 * 1024), b""):\n            h.update(block)\n    return h.hexdigest()\n\n\nclass Outputs:\n    def __init__(self, root: Path):\n        self.root = root\n        self.files = {}\n        self.writers = {}\n        self.counts = defaultdict(int)\n        root.mkdir(parents=True, exist_ok=True)\n        for table, fields in STAGES.items():\n            path = root / f"{table}.csv"\n            f = path.open("w", encoding="utf-8", newline="")\n            self.files[table] = f\n            self.writers[table] = csv.writer(f, delimiter=";", lineterminator="\\n")\n\n    def put(self, table: str, row):\n        self.writers[table].writerow(["" if x is None else x for x in row])\n        self.counts[table] += 1\n\n    def close(self):\n        for f in self.files.values():\n            f.close()\n\n\ndef rows(archive, member):\n    with archive.open(member) as raw:\n        yield from csv.DictReader(io.TextIOWrapper(raw, encoding="latin1", newline=""), delimiter=";")\n\n\ndef selected_members(names, source, year):\n    extension = ".txt" if source == "prestacao_de_contas_eleitorais_candidatos" and year in (2010, 2012, 2014, 2016) else ".csv"\n    csvs = [n for n in names if n.lower().endswith(extension)]\n    selected = []\n    if source in {"votacao_candidato_munzona", "votacao_partido_munzona", "detalhe_votacao_munzona"}:\n        selected = [n for n in csvs if any(n.upper().endswith(f"_{uf}.CSV") for uf in UFS)]\n        if source == "detalhe_votacao_munzona" and year == 2004:\n            selected += [n for n in csvs if n.upper().endswith("_BRASIL.CSV")]\n    elif source == "perfil_eleitorado" and (year < 2014 or year in (2018, 2020)):\n        selected = [n for n in csvs if n.rsplit("/", 1)[-1].upper() == f"PERFIL_ELEITORADO_{year}.CSV"]\n    elif source == "perfil_eleitorado":\n        selected = [n for n in csvs if any(n.upper().endswith(f"_{uf}.CSV") for uf in UFS)]\n    elif source == "prestacao_de_contas_eleitorais_candidatos":\n        suffix = extension.upper()\n        if year <= 2008:\n            selected = [n for n in csvs if "candidato" in n.rsplit("/", 1)[-1].lower()\n                        and any(k in n.rsplit("/", 1)[-1].lower() for k in ("receita", "despesa"))\n                        and "comite" not in n.lower() and "comitê" not in n.lower()]\n        else:\n            selected = [n for n in csvs if any(n.upper().endswith(f"_{uf}{suffix}") for uf in UFS)\n                        or (any(f"/{uf}/" in n.upper() for uf in UFS)\n                            and "candidato" in n.lower() and "comite" not in n.lower() and "comitê" not in n.lower())]\n    else:\n        selected = [n for n in csvs if any(n.upper().endswith(f"_{uf}.CSV") for uf in UFS) or n.upper().endswith("_BR.CSV")]\n    return sorted(selected)\n\n\ndef val(r, key, default=None):\n    return r.get(key, default)\n\n\n@lru_cache(maxsize=512)\ndef finance_header(value):\n    """Canonicalize a TSE legacy header once; headers repeat on every row."""\n    return "_".join(\n        "".join(ch for ch in unicodedata.normalize("NFKD", value)\n                if not unicodedata.combining(ch)).upper().split()\n    ).replace("Ç", "C")\n\n\ndef finance_fields(row):\n    return {finance_header(name.strip(\'"\')): value for name, value in row.items()}\n\n\ndef finance_val(fields, key, default=None):\n    """Read normalized legacy TSE fields without repeatedly scanning headers."""\n    aliases = {\n        "SQ_CANDIDATO": "SEQUENCIAL_CANDIDATO",\n        "VR_RECEITA": "VALOR_RECEITA",\n        "DS_FONTE_RECEITA": "FONTE_RECURSO",\n        "DS_DESPESA": "DESCRICAO_DA_DESPESA",\n        "DS_CATEGORIA_DESPESA": "TIPO_DESPESA",\n    }\n    canonical = finance_header(key)\n    if canonical in fields:\n        return fields[canonical]\n    wanted = finance_header(aliases.get(key, key))\n    value = fields.get(wanted)\n    if value is not None:\n        return value\n    legacy_aliases = {\n        "DS_FONTE_RECEITA": ("DS_TITULO", "DS_ESP_RECURSO", "TIPO_RECEITA", "DESCRICAO_TIPO_RECEITA", "DESCRICAO_TIPO_RECURSO"),\n        "DS_DESPESA": ("DS_TITULO", "TIPO_DESPESA", "DESCRICAO_DA_DESPESA"),\n        "DS_CATEGORIA_DESPESA": ("TIPO_DESPESA", "DS_TITULO", "DESCRICAO_DA_DESPESA"),\n    }\n    for alias in legacy_aliases.get(key, ()):\n        alias = finance_header(alias)\n        for source_name, value in fields.items():\n            if source_name == alias or alias in source_name:\n                return value if value is not None else default\n    return default\n\n\ndef normalized_name(value):\n    value = unicodedata.normalize("NFKD", (value or "").strip())\n    value = "".join(ch for ch in value if not unicodedata.combining(ch)).upper()\n    return " ".join("".join(ch if ch.isalnum() else " " for ch in value).split())\n\n\ndef mun_code(value):\n    """Normalize TSE numeric municipality codes without losing leading zeroes."""\n    value = (value or "").strip()\n    return value.zfill(5) if value.isdigit() and len(value) < 5 else value\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--zip-dir", type=Path, default=Path("/tmp/tse_full_2004_2024"))\n    ap.add_argument("--output", type=Path, default=Path("/tmp/tse_railway_stage"))\n    ap.add_argument("--legacy-key-map", type=Path, help="Mapa externo ano/UF/SQ original/SQ projeto para preservar chaves já publicadas de 2006/2008")\n    args = ap.parse_args()\n    out = Outputs(args.output)\n    manifests = []\n    municipalities = {}\n    expected_zones = set()\n    profile_counts = defaultdict(int)\n    profile_invalid = 0\n    account_candidates = defaultdict(set)\n    final_dates = defaultdict(set)\n    finance_members = []\n    finance_files_loaded = set()\n    receipt_keys = set()\n    duplicate_receipt_rows_dropped = 0\n    expense_keys = set()\n    duplicate_expense_rows_dropped = 0\n    candidate_sqs = defaultdict(set)\n    bem_ordem_interna = defaultdict(int)\n    candidate_2004_keys = defaultdict(set)\n    candidate_2004_by_scope = defaultdict(set)\n    candidate_2004_by_raw_scope = defaultdict(set)\n    candidate_2004_finance_number = defaultdict(set)\n    candidate_2004_ids = {}\n    candidate_2004_id_keys = {}\n    historical_vote_unmatched = 0\n    finance_unmatched_rows = defaultdict(int)\n    excluded_supplementary_rows = defaultdict(int)\n    sparse_legacy_candidates = set()\n    legacy_ids = {}\n    legacy_id_scopes = {}\n    legacy_registration_scopes = {}\n    quarantine_file = (args.output / "quarentena_identificadores.jsonl").open("w", encoding="utf-8")\n\n    def quarantine(year, source, source_file, record, reason):\n        quarantine_file.write(json.dumps({"year":year,"source":source,"source_file":source_file,\n                                         "reason":reason,"record":record},ensure_ascii=False)+"\\n")\n    if args.legacy_key_map:\n        with args.legacy_key_map.open(encoding="utf-8", newline="") as f:\n            for row in csv.DictReader(f, delimiter=";"):\n                key = (int(row["ano_eleicao"]), row["sg_uf"], row["sq_candidato_tse"])\n                value = row["sq_candidato"]\n                if key in legacy_ids and legacy_ids[key] != value:\n                    raise RuntimeError("Mapa legado contém duas chaves para o mesmo escopo")\n                if (key[0], value) in legacy_id_scopes and legacy_id_scopes[(key[0], value)] != key:\n                    raise RuntimeError("Mapa legado reutiliza SQ interno entre UFs")\n                legacy_ids[key] = value\n                legacy_id_scopes[(key[0], value)] = key\n\n    def project_sq_legacy(year, uf, raw_sq):\n        key = (year, uf, raw_sq)\n        if key not in legacy_ids:\n            digest = hashlib.blake2b("\\x1f".join(map(str, key)).encode("utf-8"), digest_size=8).digest()\n            value = str(year * 1_000_000_000_000 + int.from_bytes(digest, "big") % 1_000_000_000_000_000)\n            if (year, value) in legacy_id_scopes and legacy_id_scopes[(year, value)] != key:\n                raise RuntimeError("Colisão no SQ interno legado por ano/UF/SQ")\n            legacy_ids[key] = value\n            legacy_id_scopes[(year, value)] = key\n        candidate_sqs[year].add(legacy_ids[key])\n        return legacy_ids[key]\n\n    def project_sq_2004(scope_key):\n        if scope_key not in candidate_2004_ids:\n            id_digest = hashlib.blake2b("\\x1f".join(scope_key).encode("utf-8"), digest_size=8).digest()\n            project_sq = 2_004_000_000_000_000 + int.from_bytes(id_digest, "big") % 1_000_000_000_000_000\n            prior_key = candidate_2004_id_keys.get(project_sq)\n            if prior_key is not None and prior_key != scope_key:\n                raise RuntimeError("Colisão no ID interno derivado para candidatura de 2004")\n            candidate_2004_ids[scope_key] = str(project_sq)\n            candidate_2004_id_keys[project_sq] = scope_key\n        sq = candidate_2004_ids[scope_key]\n        uf, ue, office, source_sq, number, name = scope_key\n        candidate_2004_keys[(uf, ue, office, number, name)].add(sq)\n        candidate_2004_by_scope[(uf, ue, office, source_sq, number)].add(sq)\n        candidate_2004_by_raw_scope[(uf, ue, office, source_sq)].add(sq)\n        candidate_2004_finance_number[(uf, ue, office, number)].add(sq)\n        candidate_sqs[2004].add(sq)\n        return sq\n\n    try:\n        for year in YEARS:\n            for source in SOURCES:\n                if source == "consulta_cand_complementar" and year < 2018:\n                    continue\n                if source == "bem_candidato" and year == 2004:\n                    continue\n                path = args.zip_dir / f"{source}_{year}.zip"\n                if not path.exists():\n                    raise FileNotFoundError(path)\n                digest = sha256(path)\n                bytes_read = 0\n                selected = 0\n                with zipfile.ZipFile(path) as z:\n                    members = selected_members(z.namelist(), source, year)\n                    if not members:\n                        raise RuntimeError(f"Nenhum membro selecionado: {source}/{year}")\n                    for member in members:\n                        selected += 1\n                        base = member.rsplit("/", 1)[-1]\n                        if source == "prestacao_de_contas_eleitorais_candidatos":\n                            if year < 2018:\n                                lower_base = base.lower()\n                                kind = "receitas_candidatos" if "receita" in lower_base else (\n                                    "despesas_candidatos" if "despesa" in lower_base else None\n                                )\n                                if kind is None:\n                                    continue\n                                source_file = base\n                                for row_number, r in enumerate(rows(z, member), start=1):\n                                    fields = finance_fields(r)\n                                    sq = (finance_val(fields, "SQ_CANDIDATO", "") or "").strip()\n                                    if year == 2004:\n                                        state = (fields.get("SG_UE_SUP") or "").strip().upper()\n                                        if state not in UFS:\n                                            continue\n                                        ue = mun_code(fields.get("SG_UE"))\n                                        office = (fields.get("CD_CARGO") or "").strip()\n                                        number = (fields.get("NR_CAND") or "").strip().lstrip("0")\n                                        name = normalized_name(fields.get("NO_CAND"))\n                                        matches = candidate_2004_keys[(state, ue, office, number, name)]\n                                        if len(matches) != 1:\n                                            matches = candidate_2004_finance_number[(state, ue, office, number)]\n                                        sqs = matches\n                                    elif year in (2006, 2008):\n                                        state = (fields.get("SG_UE_SUPERIOR") or fields.get("SG_UE_SUP")\n                                                 or fields.get("UNIDADE_ELEITORAL_CANDIDATO") or "").strip().upper()\n                                        if state not in UFS and state != "BR":\n                                            continue\n                                        scope = legacy_registration_scopes.get((year, state, sq))\n                                        finance_office = (fields.get("CD_CARGO") or fields.get("CODIGO_CARGO") or "").strip()\n                                        finance_ue = (fields.get("SG_UE") or fields.get("UNIDADE_ELEITORAL_CANDIDATO") or "").strip()\n                                        if scope and ((finance_office and finance_office != scope[1])\n                                                      or (finance_ue and mun_code(finance_ue) != scope[0])):\n                                            finance_unmatched_rows[(year, kind + "_escopo_divergente")] += 1\n                                            quarantine(year,kind,source_file,r,"circunscricao_ou_cargo_divergente")\n                                            continue\n                                        mapped = legacy_ids.get((year, state, sq))\n                                        sqs = {mapped} if mapped and mapped in candidate_sqs[year] else set()\n                                    else:\n                                        sqs = {sq} if sq.isdigit() and sq in candidate_sqs[year] else set()\n                                    if len(sqs) != 1:\n                                        finance_unmatched_rows[(year, kind)] += 1\n                                        quarantine(year,kind,source_file,r,"sem_candidatura_univoca")\n                                        continue\n                                    sq = next(iter(sqs))\n                                    fingerprint = f"{source_file}:{row_number}"\n                                    if kind == "receitas_candidatos":\n                                        key = (year, sq, fingerprint)\n                                        if key in receipt_keys:\n                                            duplicate_receipt_rows_dropped += 1\n                                            continue\n                                        receipt_keys.add(key)\n                                        out.put("receita_candidato", [\n                                            year, sq, fingerprint,\n                                            finance_val(fields, "DS_FONTE_RECEITA"),\n                                            finance_val(fields, "VR_RECEITA"), None, source_file\n                                        ])\n                                    else:\n                                        key = (year, sq, fingerprint)\n                                        if key in expense_keys:\n                                            duplicate_expense_rows_dropped += 1\n                                            continue\n                                        expense_keys.add(key)\n                                        # Os leiautes antigos publicam valor declarado, sem campo\n                                        # equivalente a despesa paga. Mantemos descrição/categoria;\n                                        # VR_PAGO fica NULL até decisão semântica do grupo.\n                                        out.put("despesa_candidato", [\n                                            year, sq, fingerprint,\n                                            finance_val(fields, "DS_DESPESA"),\n                                            finance_val(fields, "DS_CATEGORIA_DESPESA"), None, source_file\n                                        ])\n                                continue\n                            kind = next((x for x in ("receitas_candidatos", "despesas_pagas_candidatos", "despesas_contratadas_candidatos") if x in base.lower()), None)\n                            if kind is None or "doador_originario" in base.lower():\n                                continue\n                            finance_files_loaded.add((year, base))\n                            for r in rows(z, member):\n                                provider = val(r, "SQ_PRESTADOR_CONTAS", "")\n                                election = val(r, "AA_ELEICAO", str(year))\n                                tp = (val(r, "TP_PRESTACAO_CONTAS", "") or "").strip().upper()\n                                dt = (val(r, "DT_PRESTACAO_CONTAS", "") or "").strip()\n                                sq = (val(r, "SQ_CANDIDATO", "") or "").strip()\n                                if provider and tp == "FINAL" and dt:\n                                    try:\n                                        final_dates[(year, provider)].add(datetime.strptime(dt, "%d/%m/%Y"))\n                                    except ValueError:\n                                        pass\n                                if provider and sq.isdigit():\n                                    account_candidates[(year, provider)].add(sq)\n                                # contratado é usado somente para vincular conta/candidatura.\n                            if kind in ("receitas_candidatos", "despesas_pagas_candidatos"):\n                                finance_members.append((year, path, member, kind, base))\n                            continue\n\n                        for r in rows(z, member):\n                            sg = (val(r, "SG_UF") or "").strip().upper()\n                            source_file = base\n                            if source in ("consulta_cand", "consulta_cand_complementar", "bem_candidato"):\n                                if source == "consulta_cand":\n                                    # A fonte de candidaturas de 2006 usa código 0\n                                    # para a eleição geral ordinária, enquanto os\n                                    # demais anos do escopo usam 2. As fontes de\n                                    # votação de 2006 já registram o tipo 2; não\n                                    # filtrar pelo código de outra tabela elimina\n                                    # candidaturas e impede o vínculo de votos e contas.\n                                    tipo_eleicao_principal = "0" if year == 2006 else "2"\n                                    if val(r, "CD_TIPO_ELEICAO") != tipo_eleicao_principal:\n                                        continue\n                                    sq = (val(r, "SQ_CANDIDATO") or "").strip()\n                                    sq_tse = sq\n                                    nr_cand = (val(r, "NR_CANDIDATO") or "").strip()\n                                    if year == 2004 and sq.isdigit():\n                                        scope_key = (\n                                            sg, mun_code(val(r, "SG_UE")),\n                                            (val(r, "CD_CARGO") or "").strip(), sq,\n                                            nr_cand.lstrip("0"), normalized_name(val(r, "NM_CANDIDATO")),\n                                        )\n                                        sq = project_sq_2004(scope_key)\n                                    elif year in (2006, 2008) and sq.isdigit():\n                                        key = (year, sg, sq)\n                                        scope = (mun_code(val(r, "SG_UE")), (val(r, "CD_CARGO") or "").strip())\n                                        if key in legacy_registration_scopes and legacy_registration_scopes[key] != scope:\n                                            raise RuntimeError("SQ legado também se repete dentro da UF; ampliar o escopo da chave antes de publicar")\n                                        legacy_registration_scopes[key] = scope\n                                        sq = project_sq_legacy(year, sg, sq)\n                                    if sq.isdigit():\n                                        candidate_sqs[year].add(sq)\n                                    out.put("candidatura", [\n                                        val(r,"ANO_ELEICAO",str(year)), val(r,"CD_ELEICAO"), val(r,"NR_TURNO"),\n                                        val(r,"CD_TIPO_ELEICAO"), val(r,"NM_TIPO_ELEICAO"), sg, mun_code(val(r,"SG_UE")), val(r,"NM_UE"),\n                                        val(r,"CD_CARGO"), val(r,"DS_CARGO"), sq, sq_tse, val(r,"NR_CPF_CANDIDATO"),\n                                        val(r,"NM_CANDIDATO"), val(r,"NM_URNA_CANDIDATO"), val(r,"DT_NASCIMENTO"), val(r,"DS_GRAU_INSTRUCAO"), val(r,"DS_GENERO"),\n                                        val(r,"DS_COR_RACA"), val(r,"NR_PARTIDO"), val(r,"SG_PARTIDO"), val(r,"NM_PARTIDO"),\n                                        val(r,"DS_SIT_TOT_TURNO"), source_file, val(r,"NR_TITULO_ELEITORAL_CANDIDATO"), nr_cand])\n                                elif source == "consulta_cand_complementar":\n                                    out.put("candidatura_complementar", [val(r,"ANO_ELEICAO",str(year)),val(r,"CD_ELEICAO"),val(r,"SQ_CANDIDATO"),val(r,"NR_TURNO"),val(r,"NM_TIPO_DESTINACAO_VOTOS"),source_file])\n                                else:\n                                    code = mun_code(val(r,"CD_MUNICIPIO"))\n                                    nm = val(r,"NM_MUNICIPIO")\n                                    if code and sg in UFS and nm:\n                                        municipalities.setdefault(code,(code,None,nm,sg,source_file))\n                                    bem_year = (val(r,"ANO_ELEICAO",str(year)) or str(year)).strip()\n                                    bem_sq = (val(r,"SQ_CANDIDATO") or "").strip()\n                                    if year in (2006, 2008):\n                                        if val(r, "CD_TIPO_ELEICAO") == "1":\n                                            excluded_supplementary_rows[(year, "bem_candidato")] += 1\n                                            continue\n                                        mapped = legacy_ids.get((year, sg, bem_sq))\n                                        scope = legacy_registration_scopes.get((year, sg, bem_sq))\n                                        if not mapped or (scope and mun_code(val(r,"SG_UE")) != scope[0]):\n                                            finance_unmatched_rows[(year, "bem_candidato")] += 1\n                                            quarantine(year,"bem_candidato",source_file,r,"sem_candidatura_univoca")\n                                            continue\n                                        bem_sq = mapped\n                                    bem_key = (bem_year, bem_sq)\n                                    bem_ordem_interna[bem_key] += 1\n                                    # O número de ordem publicado varia por leiaute e\n                                    # pode se repetir para bens distintos. O DER precisa\n                                    # de um discriminador estável dentro da candidatura;\n                                    # usamos a ordem de leitura determinística do ZIP.\n                                    out.put("bem_candidato", [bem_year,bem_sq,bem_ordem_interna[bem_key],val(r,"DS_TIPO_BEM_CANDIDATO"),val(r,"DS_BEM_CANDIDATO"),val(r,"VR_BEM_CANDIDATO"),source_file])\n                            elif source == "votacao_candidato_munzona":\n                                if sg not in UFS:\n                                    continue\n                                code=mun_code(val(r,"CD_MUNICIPIO"))\n                                sq_voto = (val(r,"SQ_CANDIDATO") or "").strip()\n                                if year in (2006, 2008):\n                                    if val(r, "CD_TIPO_ELEICAO") == "1":\n                                        excluded_supplementary_rows[(year, source)] += 1\n                                        continue\n                                    candidate_uf = "BR" if val(r, "CD_CARGO") == "1" else sg\n                                    raw_sq_voto = sq_voto\n                                    mapped = legacy_ids.get((year, candidate_uf, sq_voto))\n                                    scope = (mun_code(val(r,"SG_UE")), (val(r,"CD_CARGO") or "").strip())\n                                    known_scope = legacy_registration_scopes.get((year,candidate_uf,sq_voto))\n                                    if known_scope and known_scope != scope:\n                                        historical_vote_unmatched += 1\n                                        quarantine(year,source,source_file,r,"circunscricao_ou_cargo_divergente")\n                                        continue\n                                    if not mapped:\n                                        if not sq_voto.isdigit() or int(sq_voto) <= 0 or val(r,"CD_TIPO_ELEICAO") != "2":\n                                            historical_vote_unmatched += 1\n                                            quarantine(year,source,source_file,r,"sem_candidatura_univoca")\n                                            continue\n                                        mapped = project_sq_legacy(year,candidate_uf,sq_voto)\n                                        legacy_registration_scopes[(year,candidate_uf,sq_voto)] = scope\n                                        sparse_legacy_candidates.add((year,candidate_uf,sq_voto))\n                                    if (year,candidate_uf,raw_sq_voto) in sparse_legacy_candidates:\n                                        out.put("candidatura", [\n                                            val(r,"ANO_ELEICAO",str(year)),val(r,"CD_ELEICAO"),val(r,"NR_TURNO"),\n                                            val(r,"CD_TIPO_ELEICAO"),val(r,"NM_TIPO_ELEICAO"),candidate_uf,scope[0],val(r,"NM_UE"),\n                                            val(r,"CD_CARGO"),val(r,"DS_CARGO"),mapped,raw_sq_voto,None,\n                                            val(r,"NM_CANDIDATO"),val(r,"NM_URNA_CANDIDATO"),None,None,None,None,\n                                            val(r,"NR_PARTIDO"),val(r,"SG_PARTIDO"),val(r,"NM_PARTIDO"),\n                                            val(r,"DS_SIT_TOT_TURNO"),f"resultado:{source_file}",None,val(r,"NR_CANDIDATO")\n                                        ])\n                                    sq_voto = mapped\n                                if year == 2004:\n                                    raw_sq_voto = sq_voto\n                                    raw_scope = (sg, code, (val(r,"CD_CARGO") or "").strip(), sq_voto)\n                                    matches = candidate_2004_by_raw_scope[raw_scope]\n                                    if len(matches) == 1:\n                                        sq_voto = next(iter(matches))\n                                    else:\n                                        scope = (*raw_scope, (val(r,"NR_CANDIDATO") or "").strip().lstrip("0"))\n                                        matches = candidate_2004_by_scope[scope]\n                                        if len(matches) != 1:\n                                            candidate_name = normalized_name(val(r,"NM_CANDIDATO"))\n                                            matches = candidate_2004_keys[(sg, code, scope[2], scope[4], candidate_name)]\n                                        if len(matches) == 1:\n                                            sq_voto = next(iter(matches))\n                                        else:\n                                            raw_number = (val(r,"NR_CANDIDATO") or "").strip().lstrip("0")\n                                            candidate_name = normalized_name(val(r,"NM_CANDIDATO"))\n                                            scope_key = (*raw_scope, raw_number, candidate_name)\n                                            sq_voto = project_sq_2004(scope_key)\n                                            # A small number of result rows have no matching registration\n                                            # row in the 2004 candidate extract. Preserve the official\n                                            # result as a sparse candidacy instead of dropping its votes.\n                                            out.put("candidatura", [\n                                                val(r,"ANO_ELEICAO",str(year)), val(r,"CD_ELEICAO"), val(r,"NR_TURNO"),\n                                                val(r,"CD_TIPO_ELEICAO"), val(r,"NM_TIPO_ELEICAO"), sg, code, val(r,"NM_UE"),\n                                                val(r,"CD_CARGO"), val(r,"DS_CARGO"), sq_voto, raw_sq_voto, None,\n                                                val(r,"NM_CANDIDATO"), val(r,"NM_URNA_CANDIDATO"), None, None, None, None,\n                                                val(r,"NR_PARTIDO"), val(r,"SG_PARTIDO"), val(r,"NM_PARTIDO"),\n                                                val(r,"DS_SIT_TOT_TURNO"), f"resultado:{source_file}", None, val(r,"NR_CANDIDATO")\n                                            ])\n                                if code and sg in UFS and val(r,"NM_MUNICIPIO"):\n                                    municipalities.setdefault(code,(code,None,val(r,"NM_MUNICIPIO"),sg,source_file))\n                                out.put(source,[val(r,"ANO_ELEICAO",str(year)),sg,val(r,"CD_ELEICAO"),val(r,"NR_TURNO"),val(r,"CD_CARGO"),code,sq_voto,val(r,"QT_VOTOS_NOMINAIS"),source_file])\n                            elif source == "votacao_partido_munzona":\n                                if sg not in UFS:\n                                    continue\n                                code=mun_code(val(r,"CD_MUNICIPIO"))\n                                if code and sg in UFS and val(r,"NM_MUNICIPIO"):\n                                    municipalities.setdefault(code,(code,None,val(r,"NM_MUNICIPIO"),sg,source_file))\n                                out.put(source,[val(r,"ANO_ELEICAO",str(year)),sg,val(r,"CD_ELEICAO"),val(r,"NR_TURNO"),val(r,"CD_CARGO"),code,val(r,"NR_PARTIDO"),val(r,"SG_PARTIDO"),val(r,"QT_TOTAL_VOTOS_LEG_VALIDOS",val(r,"QT_VOTOS_LEGENDA")),val(r,"QT_VOTOS_NOMINAIS_VALIDOS",val(r,"QT_VOTOS_NOMINAIS")),source_file])\n                            elif source == "detalhe_votacao_munzona":\n                                if sg not in UFS:\n                                    continue\n                                code=mun_code(val(r,"CD_MUNICIPIO"))\n                                if code and sg in UFS and val(r,"NM_MUNICIPIO"):\n                                    municipalities.setdefault(code,(code,None,val(r,"NM_MUNICIPIO"),sg,source_file))\n                                out.put(source,[val(r,"ANO_ELEICAO",str(year)),sg,val(r,"CD_ELEICAO"),val(r,"NR_TURNO"),val(r,"CD_CARGO"),code,val(r,"NR_ZONA"),val(r,"QT_APTOS"),val(r,"QT_COMPARECIMENTO"),val(r,"QT_ABSTENCOES"),source_file])\n                                if code and sg in UFS:\n                                    expected_zones.add((val(r,"ANO_ELEICAO",str(year)),val(r,"CD_ELEICAO"),val(r,"NR_TURNO"),code,val(r,"NR_ZONA"),digest))\n                            elif source == "perfil_eleitorado":\n                                if sg not in UFS:\n                                    continue\n                                code=mun_code(val(r,"CD_MUNICIPIO"))\n                                if code and val(r,"NM_MUNICIPIO"):\n                                    municipalities.setdefault(code,(code,None,val(r,"NM_MUNICIPIO"),sg,source_file))\n                                qty=val(r,"QT_ELEITORES",val(r,"QT_ELEITORES_PERFIL")) or ""\n                                age=(val(r,"DS_FAIXA_ETARIA") or "").strip()\n                                if code and code.isdigit() and age and qty.isdigit():\n                                    profile_counts[(val(r,"ANO_ELEICAO",val(r,"AA_ELEICAO",str(year))),sg,code,age)]+=int(qty)\n                                else:\n                                    profile_invalid += 1\n                        # Consuming every selected CSV to EOF verifies its ZIP CRC.\n                manifests.append({"year":year,"source":source,"file":path.name,"sha256":digest,"zip_bytes":path.stat().st_size,"members_selected":selected})\n                print(f"{year} {source}: {selected} arquivos",flush=True)\n\n        # The destination grain is municipality/year/age band. Sum the other\n        # source dimensions locally so the DB staging does not retain millions\n        # of detail rows that 04 immediately aggregates away.\n        for (year,sg,code,age),qty in profile_counts.items():\n            out.put("perfil_eleitorado_municipio",[year,sg,code,"",age,"","","",qty,"perfil_agregado_local"])\n        for row in municipalities.values():\n            out.put("municipio_correspondencia",row)\n        for z in expected_zones:\n            out.put("comparecimento_zonas_esperadas",[*z[:5],z[5],"true"])\n\n        # Only the latest final filing per provider/account is used. Expenses\n        # are taken exclusively from DESPESAS_PAGAS; receipts remain separate.\n        final_latest = {k:max(v) for k,v in final_dates.items() if v}\n        covered = set()\n        for year,path,member,kind,source_file in finance_members:\n            with zipfile.ZipFile(path) as z:\n                for r in rows(z,member):\n                    provider=(val(r,"SQ_PRESTADOR_CONTAS","") or "").strip()\n                    if not provider or final_latest.get((year,provider)) is None:\n                        continue\n                    try:\n                        dt=datetime.strptime((val(r,"DT_PRESTACAO_CONTAS","") or "").strip(),"%d/%m/%Y")\n                    except ValueError:\n                        continue\n                    if dt != final_latest[(year,provider)] or (val(r,"TP_PRESTACAO_CONTAS","") or "").strip().upper()!="FINAL":\n                        continue\n                    candidates=account_candidates.get((year,provider),set())\n                    if len(candidates)!=1:\n                        continue\n                    sq=next(iter(candidates))\n                    if kind=="receitas_candidatos":\n                        sequence=(val(r,"SQ_RECEITA","") or "").strip()\n                        if sequence:\n                            # SQ_RECEITA pode se repetir até dentro da conta.\n                            # Hash da linha original diferencia lançamentos sem\n                            # expor seus campos pessoais na chave; cópias\n                            # idênticas da mesma linha são gravadas uma vez.\n                            fingerprint=hashlib.sha256(json.dumps(\n                                r,ensure_ascii=False,sort_keys=True,\n                                separators=(",",":")\n                            ).encode("utf-8")).hexdigest()[:24]\n                            line=f"{provider}:{sequence}:{fingerprint}"\n                            key=(year,sq,line)\n                            if key in receipt_keys:\n                                duplicate_receipt_rows_dropped += 1\n                                continue\n                            receipt_keys.add(key)\n                            out.put("receita_candidato",[year,sq,line,val(r,"DS_FONTE_RECEITA"),val(r,"VR_RECEITA"),None,source_file])\n                    else:\n                        sequence=(val(r,"SQ_DESPESA","") or "").strip()\n                        installment=(val(r,"SQ_PARCELAMENTO_DESPESA","") or "").strip()\n                        fingerprint=hashlib.sha256(json.dumps(\n                            r,ensure_ascii=False,sort_keys=True,\n                            separators=(",",":")\n                        ).encode("utf-8")).hexdigest()[:24]\n                        # Algumas prestações repetem a mesma linha e SQ_DESPESA\n                        # pode ser reutilizado. O hash preserva despesas distintas\n                        # e a chave elimina somente cópias exatas.\n                        line=":".join([provider,sequence,installment,fingerprint])\n                        if line.strip(":"):\n                            key=(year,sq,line)\n                            if key in expense_keys:\n                                duplicate_expense_rows_dropped += 1\n                                continue\n                            expense_keys.add(key)\n                            out.put("despesa_candidato",[year,sq,line,val(r,"DS_DESPESA"),val(r,"DS_ORIGEM_DESPESA"),val(r,"VR_PAGTO_DESPESA"),source_file])\n                    covered.add((year,sq))\n        # A coverage row is emitted only when an account was identified from a\n        # final TSE prestação. No account is silently interpreted as zero cost.\n        for year,sq in sorted(covered):\n            digest=next((m["sha256"] for m in manifests if m["year"]==year and m["source"].startswith("prestacao_")),"")\n            out.put("cobertura_despesa_paga",[year,sq,"true",digest])\n        if legacy_ids:\n            with (args.output / "legacy_candidate_key_map.csv").open("w",encoding="utf-8",newline="") as f:\n                writer=csv.writer(f,delimiter=";",lineterminator="\\n")\n                writer.writerow(["ano_eleicao","sg_uf","sq_candidato_tse","sq_candidato"])\n                for (year,uf,raw_sq),project_sq in sorted(legacy_ids.items()):\n                    writer.writerow([year,uf,raw_sq,project_sq])\n    finally:\n        out.close()\n        quarantine_file.close()\n    summary={"years":YEARS,"ufs":sorted(UFS),"manifests":manifests,"stage_rows":dict(out.counts),"duplicate_receipt_rows_dropped":duplicate_receipt_rows_dropped,"duplicate_expense_rows_dropped":duplicate_expense_rows_dropped,"finance_unmatched_rows":{f"{y}:{kind}":n for (y,kind),n in finance_unmatched_rows.items()},"historical_vote_unmatched_rows":historical_vote_unmatched,"project_synthetic_2004_candidate_ids":len(candidate_2004_ids),"profile_invalid_source_rows":profile_invalid,"profile_aggregated_groups":len(profile_counts),"stage_csv_bytes":sum(p.stat().st_size for p in args.output.glob("*.csv")),"source_zip_bytes":sum(m["zip_bytes"] for m in manifests),"municipalities":len(municipalities),"expected_zones":len(expected_zones)}\n    summary["excluded_supplementary_rows"]={f"{y}:{kind}":n for (y,kind),n in excluded_supplementary_rows.items()}\n    summary["sparse_legacy_candidates_from_results"]=len(sparse_legacy_candidates)\n    summary["scoped_legacy_candidate_keys"]=len(legacy_ids)\n    (args.output/"manifest.json").write_text(json.dumps(summary,ensure_ascii=False,indent=2)+"\\n")\n    print(json.dumps({k:v for k,v in summary.items() if k!="manifests"},ensure_ascii=False,indent=2))\n\n\nif __name__=="__main__":\n    main()\n'
MODEL_SQL = "-- Executado pelo Flight depois de normalizar os ZIPs oficiais do TSE em\n-- tabelas temporarias locais. Publica somente as 11 tabelas do DER Joao Carlos.\n-- O banco e o schema-alvo devem ser definidos pela execucao do Flight.\n\nCREATE SCHEMA IF NOT EXISTS public;\n\nCREATE OR REPLACE TEMP MACRO texto_publicado(v) AS (\n    CASE WHEN v IS NULL OR UPPER(TRIM(v)) IN\n        ('', '#NULO', '#NULO#', '#NE', '-1', '-3', '-4', 'NÃO DIVULGÁVEL')\n    THEN NULL ELSE TRIM(v) END\n);\nCREATE OR REPLACE TEMP MACRO valor_brl(v) AS (\n    CASE\n        WHEN v IS NULL OR UPPER(TRIM(v)) IN\n            ('', '#NULO', '#NULO#', '#NE', '-1', '-3', '-4', 'NÃO DIVULGÁVEL') THEN NULL\n        WHEN CONTAINS(TRIM(v), ',') THEN\n            TRY_CAST(REPLACE(REPLACE(TRIM(v), '.', ''), ',', '.') AS DECIMAL(14,2))\n        ELSE TRY_CAST(TRIM(v) AS DECIMAL(14,2))\n    END\n);\n\n-- Resolver compartilhado: analise-eleicoes/sql/motherduck/08_resolver_identidades.sql\n-- Executar após criar stg_candidatura. Não publica tabelas auxiliares.\n-- Título/CPF são observações por ano/SQ; conflitos nunca se resolvem pelo\n-- menor ID. CPF requer dígitos verificadores + nome legal e nascimento iguais.\nCREATE OR REPLACE TEMP TABLE _identidade_escopo_guard AS\nSELECT CASE WHEN EXISTS (\n SELECT ano_eleicao,sq_candidato FROM stg_candidatura\n GROUP BY 1,2 HAVING COUNT(DISTINCT sg_uf||':'||sg_ue||':'||cd_cargo)>1\n) THEN ERROR('SQ_CANDIDATO reutilizado entre circunscrições/cargos: reprocessar as chaves históricas com escopo antes de publicar; ano/SQ não basta em 2006/2008.') ELSE TRUE END AS valido;\nCREATE OR REPLACE TEMP MACRO texto_publicado(v) AS (\n CASE WHEN v IS NULL OR UPPER(TRIM(v)) IN\n ('', '#NULO', '#NULO#', '#NE', '#NE#', '-1', '-3', '-4', 'NÃO DIVULGÁVEL')\n THEN NULL ELSE TRIM(v) END\n);\nCREATE OR REPLACE TEMP MACRO nome_identidade(v) AS (\n TRIM(REGEXP_REPLACE(STRIP_ACCENTS(UPPER(texto_publicado(v))), '[^A-Z0-9]+', ' ', 'g'))\n);\nCREATE OR REPLACE TEMP MACRO cpf_valido(v) AS (\n CASE WHEN REGEXP_FULL_MATCH(REGEXP_REPLACE(COALESCE(v, ''), '[^0-9]', '', 'g'), '[0-9]{11}')\n AND REGEXP_REPLACE(v, '[^0-9]', '', 'g') NOT IN\n ('00000000000','11111111111','22222222222','33333333333','44444444444',\n '55555555555','66666666666','77777777777','88888888888','99999999999')\n THEN ((LIST_SUM(LIST_TRANSFORM(RANGE(0,9),i -> CAST(SUBSTR(REGEXP_REPLACE(v,'[^0-9]','','g'),i+1,1) AS INTEGER)*(10-i)))*10)%11%10=CAST(SUBSTR(REGEXP_REPLACE(v,'[^0-9]','','g'),10,1) AS INTEGER)\n AND (LIST_SUM(LIST_TRANSFORM(RANGE(0,10),i -> CAST(SUBSTR(REGEXP_REPLACE(v,'[^0-9]','','g'),i+1,1) AS INTEGER)*(11-i)))*10)%11%10=CAST(SUBSTR(REGEXP_REPLACE(v,'[^0-9]','','g'),11,1) AS INTEGER))\n ELSE FALSE END\n);\n\nCREATE OR REPLACE TEMP TABLE _person_by_candidature AS\nWITH origem AS (\n SELECT TRY_CAST(ano_eleicao AS INTEGER) AS ano_eleicao,\n TRY_CAST(sq_candidato AS BIGINT) AS sq_candidato,\n CASE WHEN REGEXP_FULL_MATCH(TRIM(nr_titulo_eleitoral_candidato),'[0-9]{12}')\n AND TRIM(nr_titulo_eleitoral_candidato)<>'000000000000' THEN TRIM(nr_titulo_eleitoral_candidato) END AS titulo,\n CASE WHEN REGEXP_FULL_MATCH(REGEXP_REPLACE(COALESCE(nr_cpf_candidato,''),'[^0-9]','','g'),'[0-9]{11}')\n THEN REGEXP_REPLACE(nr_cpf_candidato,'[^0-9]','','g') END AS cpf_publicado,\n CASE WHEN cpf_valido(nr_cpf_candidato) THEN REGEXP_REPLACE(nr_cpf_candidato,'[^0-9]','','g') END AS cpf_chave,\n texto_publicado(nm_candidato) AS nome, nome_identidade(nm_candidato) AS nome_norm,\n COALESCE(TRY_STRPTIME(texto_publicado(dt_nascimento),'%d/%m/%Y')::DATE,TRY_CAST(texto_publicado(dt_nascimento) AS DATE)) AS nascimento,\n texto_publicado(ds_grau_instrucao) AS instrucao, texto_publicado(ds_genero) AS genero,\n texto_publicado(ds_cor_raca) AS raca, source_file\n FROM stg_candidatura\n WHERE TRY_CAST(ano_eleicao AS INTEGER) IS NOT NULL AND TRY_CAST(sq_candidato AS BIGINT) IS NOT NULL\n), observacao AS (\n SELECT ano_eleicao,sq_candidato,\n CASE WHEN COUNT(DISTINCT titulo)=1 THEN MAX(titulo) END AS titulo,\n CASE WHEN COUNT(DISTINCT cpf_publicado)=1 THEN MAX(cpf_publicado) END AS cpf_publicado,\n CASE WHEN COUNT(DISTINCT cpf_chave)=1 THEN MAX(cpf_chave) END AS cpf_chave,\n CASE WHEN COUNT(DISTINCT nome_norm)=1 THEN MAX(nome_norm) END AS nome_norm,\n CASE WHEN COUNT(DISTINCT nascimento)=1 THEN MAX(nascimento) END AS nascimento,\n FIRST(nome ORDER BY source_file DESC NULLS LAST,nome) AS nome,\n FIRST(instrucao ORDER BY source_file DESC NULLS LAST,instrucao) AS instrucao,\n FIRST(genero ORDER BY source_file DESC NULLS LAST,genero) AS genero,\n FIRST(raca ORDER BY source_file DESC NULLS LAST,raca) AS raca,\n COUNT(DISTINCT titulo)>1 OR COUNT(DISTINCT cpf_publicado)>1\n OR COUNT(DISTINCT nome_norm)>1 OR COUNT(DISTINCT nascimento)>1 AS conflito\n FROM origem GROUP BY 1,2\n), titulo_classes AS (\n SELECT titulo,nome_norm,nascimento,\n COUNT(DISTINCT cpf_publicado) AS cpfs_publicados,\n CASE WHEN COUNT(DISTINCT cpf_chave)=1 THEN MAX(cpf_chave) END AS cpf_consenso\n FROM observacao\n WHERE NOT conflito AND titulo IS NOT NULL AND nome_norm IS NOT NULL AND nascimento IS NOT NULL\n GROUP BY 1,2,3\n)\nSELECT p.*,\n CASE WHEN p.conflito OR p.nome_norm IS NULL OR p.nascimento IS NULL\n THEN 'C:'||p.ano_eleicao||':'||p.sq_candidato\n WHEN p.cpf_chave IS NOT NULL\n THEN 'P:'||p.cpf_chave||':'||SHA256(p.nome_norm||':'||p.nascimento::VARCHAR)\n WHEN t.cpfs_publicados<=1 AND t.cpf_consenso IS NOT NULL\n THEN 'P:'||t.cpf_consenso||':'||SHA256(p.nome_norm||':'||p.nascimento::VARCHAR)\n WHEN t.cpfs_publicados<=1\n THEN 'T:'||p.titulo||':'||SHA256(p.nome_norm||':'||p.nascimento::VARCHAR)\n ELSE 'C:'||p.ano_eleicao||':'||p.sq_candidato END AS chave_pessoa\nFROM observacao p LEFT JOIN titulo_classes t USING(titulo,nome_norm,nascimento);\n\nCREATE OR REPLACE TEMP TABLE _person_ids AS\nSELECT chave_pessoa,ROW_NUMBER() OVER(ORDER BY chave_pessoa)::INTEGER AS id_pessoa_projeto\nFROM (SELECT DISTINCT chave_pessoa FROM _person_by_candidature);\n\nCREATE OR REPLACE TABLE public.candidato AS\nSELECT ids.id_pessoa_projeto,\n FIRST(p.titulo ORDER BY p.titulo IS NULL,p.ano_eleicao DESC,p.sq_candidato DESC) AS nr_titulo_eleitoral_candidato,\n FIRST(p.cpf_publicado ORDER BY p.cpf_chave IS NULL,p.cpf_publicado IS NULL,p.ano_eleicao DESC,p.sq_candidato DESC) AS nr_cpf_candidato,\n FIRST(p.nome ORDER BY p.ano_eleicao DESC,p.sq_candidato DESC) AS nm_candidato,\n FIRST(p.nascimento ORDER BY p.ano_eleicao DESC,p.sq_candidato DESC) AS dt_nascimento,\n FIRST(p.instrucao ORDER BY p.ano_eleicao DESC,p.sq_candidato DESC) AS ds_grau_instrucao,\n FIRST(p.genero ORDER BY p.ano_eleicao DESC,p.sq_candidato DESC) AS ds_genero,\n FIRST(p.raca ORDER BY p.ano_eleicao DESC,p.sq_candidato DESC) AS ds_cor_raca\nFROM _person_by_candidature p JOIN _person_ids ids USING(chave_pessoa)\nGROUP BY ids.id_pessoa_projeto;\n\nCREATE OR REPLACE TABLE public.municipio AS\nSELECT\n    texto_publicado(cd_municipio_tse) AS cd_municipio_tse,\n    CAST(NULL AS VARCHAR) AS cd_municipio_ibge,\n    FIRST(texto_publicado(nm_municipio) ORDER BY (texto_publicado(nm_municipio) IS NOT NULL) DESC) AS nm_municipio,\n    FIRST(UPPER(texto_publicado(sg_uf)) ORDER BY (texto_publicado(sg_uf) IS NOT NULL) DESC) AS sg_uf,\n    CAST(NULL AS DECIMAL(14,2)) AS pib_per_capita,\n    CAST(NULL AS DECIMAL(4,3)) AS idhm,\n    CAST(NULL AS INTEGER) AS populacao_total\nFROM stg_municipio\nWHERE texto_publicado(cd_municipio_tse) IS NOT NULL\nGROUP BY 1;\n\nCREATE OR REPLACE TABLE public.partido AS\nWITH fonte AS (\n    SELECT TRY_CAST(nr_partido AS INTEGER) AS nr_partido,\n        texto_publicado(sg_partido) AS sg_partido,\n        texto_publicado(nm_partido) AS nm_partido,\n           TRY_CAST(ano_eleicao AS INTEGER) AS ano_eleicao\n    FROM stg_candidatura\n    WHERE TRY_CAST(nr_partido AS INTEGER) IS NOT NULL\n    UNION ALL\n    SELECT TRY_CAST(nr_partido AS INTEGER), texto_publicado(sg_partido), NULL,\n           TRY_CAST(ano_eleicao AS INTEGER)\n    FROM stg_votacao_partido\n    WHERE TRY_CAST(nr_partido AS INTEGER) IS NOT NULL\n)\nSELECT nr_partido,\n       FIRST(sg_partido ORDER BY ano_eleicao DESC NULLS LAST) AS sg_partido,\n       FIRST(nm_partido ORDER BY (nm_partido IS NOT NULL) DESC, ano_eleicao DESC NULLS LAST) AS nm_partido,\n       CAST(NULL AS VARCHAR(50)) AS vies_politico\nFROM fonte GROUP BY nr_partido;\n\nCREATE OR REPLACE TABLE public.candidatura AS\nWITH candidaturas_base AS (\n    SELECT\n        TRY_CAST(ano_eleicao AS INTEGER) AS ano_eleicao,\n        TRY_CAST(sq_candidato AS BIGINT) AS sq_candidato,\n        TRY_CAST(NULLIF(TRIM(sq_candidato_tse), '') AS BIGINT) AS sq_candidato_tse,\n        CASE WHEN REGEXP_FULL_MATCH(TRIM(nr_titulo_eleitoral_candidato), '[0-9]{12}')\n                  AND TRIM(nr_titulo_eleitoral_candidato) <> '000000000000'\n             THEN TRIM(nr_titulo_eleitoral_candidato) END AS titulo,\n        TRY_CAST(nr_partido AS INTEGER) AS nr_partido,\n    texto_publicado(sg_ue) AS sg_ue,\n        TRY_CAST(cd_cargo AS INTEGER) AS cd_cargo,\n    texto_publicado(ds_cargo) AS ds_cargo,\n    texto_publicado(sg_partido) AS sg_partido,\n    texto_publicado(nm_urna_candidato) AS nm_urna_candidato,\n        TRY_CAST(nr_turno AS INTEGER) AS nr_turno,\n    texto_publicado(ds_sit_tot_turno) AS situacao,\n        NULLIF(TRIM(source_file), '') AS source_file\n    FROM stg_candidatura\n    WHERE TRY_CAST(ano_eleicao AS INTEGER) IS NOT NULL\n      AND TRY_CAST(sq_candidato AS BIGINT) IS NOT NULL\n      AND (UPPER(TRIM(sg_uf)) IN ('AC','AL','BA','DF','RO','SP') OR UPPER(TRIM(sg_uf)) = 'BR')\n), com_turno AS (\n    SELECT *,\n        CASE WHEN nr_turno IN (1,2) AND UPPER(TRIM(situacao)) NOT IN\n             ('2º TURNO','2° TURNO','2 TURNO','SEGUNDO TURNO') THEN nr_turno END AS turno_resultado\n    FROM candidaturas_base\n), resultado AS (\n    SELECT * FROM com_turno\n    QUALIFY ROW_NUMBER() OVER (\n        PARTITION BY ano_eleicao, sq_candidato\n        ORDER BY turno_resultado DESC NULLS LAST, source_file, situacao\n    ) = 1\n), pessoa AS (\n SELECT i.ano_eleicao,i.sq_candidato,p.chave_pessoa\n FROM resultado i JOIN _person_by_candidature p USING(ano_eleicao,sq_candidato)\n)\nSELECT\n    r.ano_eleicao, r.sq_candidato, r.sq_candidato_tse, ids.id_pessoa_projeto,\n    r.nr_partido,\n    m.cd_municipio_tse,\n    r.sg_partido,\n    r.sg_ue,\n    r.cd_cargo,\n    r.ds_cargo,\n    r.nm_urna_candidato,\n    r.turno_resultado AS nr_turno_resultado,\n    r.situacao AS ds_sit_tot_turno,\n    CAST(NULL AS VARCHAR(50)) AS vies_politico_eleicao,\n    CAST(NULL AS INTEGER) AS qt_votos_totais\nFROM resultado r\nJOIN pessoa p USING (ano_eleicao, sq_candidato)\nJOIN _person_ids ids USING (chave_pessoa)\nLEFT JOIN public.municipio m ON m.cd_municipio_tse = r.sg_ue;\n\nCREATE OR REPLACE TABLE public.bens_declarados AS\nSELECT\n    TRY_CAST(b.ano_eleicao AS INTEGER) AS ano_eleicao,\n    TRY_CAST(b.sq_candidato AS BIGINT) AS sq_candidato,\n    TRY_CAST(b.nr_ordem_bem_candidato AS INTEGER) AS id_bem,\n    texto_publicado(b.ds_tipo_bem_candidato) AS ds_tipo_bem,\n    texto_publicado(b.ds_bem_candidato) AS ds_bem,\n    valor_brl(b.vr_bem_candidato) AS vr_bem\nFROM stg_bem b\nJOIN public.candidatura c\n  ON c.ano_eleicao = TRY_CAST(b.ano_eleicao AS INTEGER)\n AND c.sq_candidato = TRY_CAST(b.sq_candidato AS BIGINT)\nWHERE TRY_CAST(b.nr_ordem_bem_candidato AS INTEGER) IS NOT NULL;\n\nCREATE OR REPLACE TABLE public.receitas_campanha AS\nWITH parse AS (\n    SELECT TRY_CAST(ano_eleicao AS INTEGER) AS ano_eleicao,\n           TRY_CAST(sq_candidato AS BIGINT) AS sq_candidato,\n           id_linha_origem,\n           texto_publicado(ds_fonte_receita) AS ds_fonte_receita,\n           valor_brl(vr_receita) AS vr_receita\n    FROM stg_receita\n)\nSELECT p.ano_eleicao, p.sq_candidato,\n       ROW_NUMBER() OVER (PARTITION BY p.ano_eleicao,p.sq_candidato ORDER BY p.id_linha_origem)::INTEGER AS id_receita,\n       ds_fonte_receita,\n       CAST(NULL AS VARCHAR(50)) AS tp_origem_recurso,\n       vr_receita\nFROM parse p\nJOIN public.candidatura c USING (ano_eleicao,sq_candidato);\n\nCREATE OR REPLACE TABLE public.despesas_pagas AS\nWITH parse AS (\n    SELECT TRY_CAST(ano_eleicao AS INTEGER) AS ano_eleicao,\n           TRY_CAST(sq_candidato AS BIGINT) AS sq_candidato,\n           id_linha_origem,\n           texto_publicado(ds_despesa) AS ds_despesa,\n           texto_publicado(ds_categoria_despesa) AS ds_categoria_despesa,\n           valor_brl(vr_pago) AS vr_pago\n    FROM stg_despesa\n)\nSELECT p.ano_eleicao, p.sq_candidato,\n       ROW_NUMBER() OVER (PARTITION BY p.ano_eleicao,p.sq_candidato ORDER BY p.id_linha_origem)::INTEGER AS id_despesa,\n       ds_despesa,\n       ds_categoria_despesa,\n       vr_pago\nFROM parse p\nJOIN public.candidatura c USING (ano_eleicao,sq_candidato);\n\nCREATE OR REPLACE TABLE public.perfil_eleitorado AS\nSELECT\n    TRY_CAST(p.ano_eleicao AS INTEGER) AS ano_eleicao,\n    TRIM(p.cd_municipio_tse) AS cd_municipio_tse,\n    TRIM(p.ds_faixa_etaria) AS ds_faixa_etaria,\n    TRY_CAST(SUM(TRY_CAST(p.qt_eleitores_perfil AS BIGINT)) AS INTEGER) AS qt_eleitores\nFROM stg_perfil p\nJOIN public.municipio m ON m.cd_municipio_tse = TRIM(p.cd_municipio_tse)\nWHERE TRY_CAST(p.qt_eleitores_perfil AS BIGINT) IS NOT NULL\nGROUP BY 1,2,3;\n\nCREATE OR REPLACE TABLE public.votacao_candidato_municipio AS\nSELECT\n    TRY_CAST(v.ano_eleicao AS INTEGER) AS ano_eleicao,\n    TRY_CAST(v.cd_eleicao AS INTEGER) AS cd_eleicao,\n    TRY_CAST(v.nr_turno AS INTEGER) AS nr_turno,\n    TRY_CAST(v.cd_cargo AS INTEGER) AS cd_cargo,\n    TRIM(v.cd_municipio_tse) AS cd_municipio_tse,\n    TRY_CAST(v.sq_candidato AS BIGINT) AS sq_candidato,\n    TRY_CAST(SUM(TRY_CAST(texto_publicado(v.qt_votos_nominais) AS BIGINT)) AS INTEGER) AS qt_votos_nominais\nFROM stg_votacao_candidato v\nJOIN public.municipio m ON m.cd_municipio_tse = TRIM(v.cd_municipio_tse)\nJOIN public.candidatura c\n  ON c.ano_eleicao = TRY_CAST(v.ano_eleicao AS INTEGER)\n AND c.sq_candidato = TRY_CAST(v.sq_candidato AS BIGINT)\nWHERE UPPER(TRIM(v.sg_uf)) IN ('AC','AL','BA','DF','RO','SP')\n  AND TRY_CAST(texto_publicado(v.qt_votos_nominais) AS BIGINT) IS NOT NULL\nGROUP BY 1,2,3,4,5,6;\n\nUPDATE public.candidatura c\nSET qt_votos_totais = v.qt_votos\nFROM (\n    SELECT ano_eleicao, sq_candidato, cd_cargo,\n           TRY_CAST(SUM(qt_votos_nominais::BIGINT) AS INTEGER) AS qt_votos\n    FROM public.votacao_candidato_municipio\n    WHERE nr_turno = 1\n    GROUP BY 1,2,3\n) v\nWHERE c.ano_eleicao=v.ano_eleicao AND c.sq_candidato=v.sq_candidato\n  AND c.cd_cargo=v.cd_cargo\n  AND (c.cd_municipio_tse IS NOT NULL OR UPPER(c.sg_ue) IN ('AC','AL','BA','DF','RO','SP'));\n\nCREATE OR REPLACE TABLE public.votacao_partido AS\nSELECT\n    TRY_CAST(v.ano_eleicao AS INTEGER) AS ano_eleicao,\n    TRY_CAST(v.cd_eleicao AS INTEGER) AS cd_eleicao,\n    TRY_CAST(v.nr_turno AS INTEGER) AS nr_turno,\n    TRY_CAST(v.cd_cargo AS INTEGER) AS cd_cargo,\n    TRIM(v.cd_municipio_tse) AS cd_municipio_tse,\n    TRY_CAST(v.nr_partido AS INTEGER) AS nr_partido,\n    NULLIF(TRIM(v.sg_partido), '') AS sg_partido,\n    TRY_CAST(SUM(TRY_CAST(v.qt_votos_legenda AS BIGINT)) AS INTEGER) AS qt_votos_legenda,\n    TRY_CAST(SUM(TRY_CAST(v.qt_votos_nominais AS BIGINT)) AS INTEGER) AS qt_votos_nominais\nFROM stg_votacao_partido v\nJOIN public.municipio m ON m.cd_municipio_tse = TRIM(v.cd_municipio_tse)\nJOIN public.partido p ON p.nr_partido = TRY_CAST(v.nr_partido AS INTEGER)\nWHERE UPPER(TRIM(v.sg_uf)) IN ('AC','AL','BA','DF','RO','SP')\nGROUP BY 1,2,3,4,5,6,7;\n\nCREATE OR REPLACE TABLE public.comparecimento_municipio AS\nWITH zonas AS (\n    SELECT\n        TRY_CAST(ano_eleicao AS INTEGER) AS ano_eleicao,\n        TRY_CAST(cd_eleicao AS INTEGER) AS cd_eleicao,\n        TRY_CAST(nr_turno AS INTEGER) AS nr_turno,\n        TRIM(cd_municipio_tse) AS cd_municipio_tse,\n        TRY_CAST(nr_zona AS INTEGER) AS nr_zona,\n        COUNT(DISTINCT (TRY_CAST(qt_aptos AS BIGINT), TRY_CAST(qt_comparecimento AS BIGINT), TRY_CAST(qt_abstencao AS BIGINT))) AS combinacoes,\n        MAX(TRY_CAST(qt_aptos AS BIGINT)) AS aptos,\n        MAX(TRY_CAST(qt_comparecimento AS BIGINT)) AS presentes,\n        MAX(TRY_CAST(qt_abstencao AS BIGINT)) AS ausentes,\n        BOOL_AND(TRY_CAST(qt_aptos AS BIGINT) IS NOT NULL AND TRY_CAST(qt_comparecimento AS BIGINT) IS NOT NULL\n                 AND TRY_CAST(qt_abstencao AS BIGINT) IS NOT NULL\n                 AND TRY_CAST(qt_aptos AS BIGINT)=TRY_CAST(qt_comparecimento AS BIGINT)+TRY_CAST(qt_abstencao AS BIGINT)) AS medidas_validas\n    FROM stg_detalhe\n    WHERE UPPER(TRIM(sg_uf)) IN ('AC','AL','BA','DF','RO','SP')\n    GROUP BY 1,2,3,4,5\n), municipios_completos AS (\n    SELECT ano_eleicao,cd_eleicao,nr_turno,cd_municipio_tse,\n           BOOL_AND(combinacoes=1 AND medidas_validas) AS completo,\n           COUNT(*) AS zonas,\n           SUM(aptos) AS aptos,\n           SUM(presentes) AS presentes,\n           SUM(ausentes) AS ausentes\n    FROM zonas\n    GROUP BY 1,2,3,4\n)\nSELECT c.ano_eleicao,c.cd_eleicao,c.nr_turno,c.cd_municipio_tse,\n       CAST(c.aptos AS INTEGER) AS qt_aptos,\n       CAST(c.presentes AS INTEGER) AS qt_comparecimento,\n       CAST(c.ausentes AS INTEGER) AS qt_abstencao\nFROM municipios_completos c\nJOIN public.municipio m USING(cd_municipio_tse)\nWHERE c.completo\n  AND c.aptos BETWEEN 0 AND 2147483647\n  AND c.presentes BETWEEN 0 AND 2147483647\n  AND c.ausentes BETWEEN 0 AND 2147483647;\n\n-- Não carregar tabelas auxiliares/staging do pipeline no banco publicado.\n"
VIEWS_SQL = '-- Views analíticas do modelo TSE para DuckDB/MotherDuck.\n-- Pré-requisito: as 11 tabelas do DER já devem estar no schema public\n-- do banco BDR-TSE.\n-- Execute conectado ao banco BDR-TSE.\n\nCREATE SCHEMA IF NOT EXISTS public;\n\nCREATE OR REPLACE VIEW public.v_partidos_eleitos AS\nSELECT\n    c.ano_eleicao,\n    COALESCE(m.sg_uf, c.sg_ue) AS uf,\n    c.nr_partido,\n    c.sg_partido,\n    CASE WHEN p.sg_partido = c.sg_partido THEN p.nm_partido END AS nm_partido,\n    c.ds_cargo,\n    COUNT(*) AS qt_eleitos\nFROM public.candidatura c\nLEFT JOIN public.municipio m\n    ON m.cd_municipio_tse = c.cd_municipio_tse\nLEFT JOIN public.partido p\n    ON p.nr_partido = c.nr_partido\nWHERE c.ds_sit_tot_turno IN (\'ELEITO\', \'ELEITO POR QP\', \'ELEITO POR MÉDIA\')\n  AND c.ds_cargo NOT LIKE \'%VICE%\'\n  AND c.ds_cargo NOT LIKE \'%SUPLENTE%\'\nGROUP BY 1, 2, 3, 4, 5, 6;\n\n-- Mantém a view existente usada pelo mapa. As quatro faixas são intervalos\n-- iguais em reais (WIDTH_BUCKET), e não quartis por quantidade de candidatos.\nCREATE OR REPLACE VIEW public.v_gasto_sucesso AS\nWITH gastos_candidato AS (\n    SELECT ano_eleicao, sq_candidato, SUM(vr_pago) AS total_gasto\n    FROM public.despesas_pagas\n    GROUP BY ano_eleicao, sq_candidato\n),\nbase_candidatos AS (\n    SELECT\n        c.ano_eleicao,\n        COALESCE(m.sg_uf, c.sg_ue) AS uf,\n        c.ds_cargo,\n        c.sq_candidato,\n        CASE\n            WHEN c.ds_sit_tot_turno IN (\'ELEITO\', \'ELEITO POR QP\', \'ELEITO POR MÉDIA\') THEN 1\n            ELSE 0\n        END AS flag_eleito,\n        g.total_gasto,\n        MAX(g.total_gasto) OVER (\n            PARTITION BY c.ano_eleicao, COALESCE(m.sg_uf, c.sg_ue), c.ds_cargo\n        ) AS teto_maximo_cargo_ano\n    FROM public.candidatura c\n    LEFT JOIN public.municipio m\n        ON c.cd_municipio_tse = m.cd_municipio_tse\n    INNER JOIN gastos_candidato g\n        USING (ano_eleicao, sq_candidato)\n    WHERE c.ds_cargo NOT LIKE \'%VICE%\'\n      AND c.ds_cargo NOT LIKE \'%SUPLENTE%\'\n      AND c.ds_sit_tot_turno NOT IN (\n          \'INDEFERIDO\', \'CASSADO\', \'FALECIDO\', \'CANCELADO\',\n          \'NÃO CONHECIDO\', \'RENÚNCIA\'\n      )\n      AND c.ds_sit_tot_turno IS NOT NULL\n      AND g.total_gasto IS NOT NULL\n),\nfaixas_gasto AS (\n    SELECT\n        *,\n        CASE\n            WHEN total_gasto < 0 THEN 0\n            WHEN total_gasto >= teto_maximo_cargo_ano + 0.01 THEN 5\n            ELSE CAST(FLOOR(total_gasto * 4 / (teto_maximo_cargo_ano + 0.01)) AS INTEGER) + 1\n        END AS faixa_financeira\n    FROM base_candidatos\n)\nSELECT\n    ano_eleicao,\n    uf,\n    ds_cargo,\n    faixa_financeira,\n    ROUND((MAX(teto_maximo_cargo_ano) + 0.01) * (faixa_financeira - 1) / 4, 2)\n        AS limite_inferior_faixa,\n    ROUND((MAX(teto_maximo_cargo_ano) + 0.01) * faixa_financeira / 4, 2)\n        AS limite_superior_faixa,\n    CAST(MIN(total_gasto) AS DECIMAL(14, 2)) AS piso_faixa,\n    CAST(MAX(total_gasto) AS DECIMAL(14, 2)) AS teto_faixa,\n    COUNT(*) AS qtd_candidatos_na_faixa,\n    SUM(flag_eleito) AS qtd_eleitos,\n    ROUND(SUM(flag_eleito)::DECIMAL / COUNT(*) * 100, 2) AS taxa_sucesso_pct,\n    ROUND(AVG(total_gasto) FILTER (WHERE flag_eleito = 1), 2) AS media_gasto_eleitos,\n    ROUND(AVG(total_gasto) FILTER (WHERE flag_eleito = 0), 2) AS media_gasto_nao_eleitos,\n    CAST(quantile_cont(total_gasto, 0.5) FILTER (WHERE flag_eleito = 1) AS DECIMAL(14, 2))\n        AS mediana_gasto_eleitos,\n    CAST(quantile_cont(total_gasto, 0.5) FILTER (WHERE flag_eleito = 0) AS DECIMAL(14, 2))\n        AS mediana_gasto_nao_eleitos\nFROM faixas_gasto\nGROUP BY ano_eleicao, uf, ds_cargo, faixa_financeira;\n\n-- View oficial da Questão 2, conforme definição validada pelo grupo.\n-- Mantém a saída usada no HTML e deriva da regra financeira acima.\nCREATE OR REPLACE VIEW public.vw_questao_2_despesas AS\nSELECT\n    ano_eleicao,\n    uf,\n    ds_cargo,\n    faixa_financeira,\n    piso_faixa AS "piso_faixa_r$",\n    teto_faixa AS "teto_faixa_r$",\n    qtd_candidatos_na_faixa,\n    qtd_eleitos,\n    taxa_sucesso_pct,\n    media_gasto_eleitos,\n    media_gasto_nao_eleitos,\n    mediana_gasto_eleitos,\n    mediana_gasto_nao_eleitos\nFROM public.v_gasto_sucesso;\n\n-- Histórico por candidatura. JSON/JSONB PostgreSQL é representado como JSON\n-- DuckDB; list(...) preserva o conteúdo aninhado consumido pela interface.\nCREATE OR REPLACE VIEW public.v_historico_candidato AS\nWITH receita_linhas AS (\n    SELECT\n        rc.ano_eleicao,\n        rc.sq_candidato,\n        rc.ds_fonte_receita AS fonte,\n        COALESCE(\n            NULLIF(rc.tp_origem_recurso, \'\'),\n            CASE\n                WHEN rc.ds_fonte_receita IN (\'FUNDO ESPECIAL\', \'FUNDO PARTIDARIO\') THEN \'PÚBLICO\'\n                WHEN rc.ds_fonte_receita = \'OUTROS RECURSOS\' THEN \'PRIVADO\'\n                ELSE \'INDEFINIDO\'\n            END\n        ) AS origem,\n        SUM(rc.vr_receita) AS valor,\n        COUNT(*) AS qtd\n    FROM public.receitas_campanha rc\n    GROUP BY 1, 2, 3, 4\n),\nreceitas AS (\n    SELECT\n        ano_eleicao,\n        sq_candidato,\n        SUM(valor) AS total_receitas,\n        SUM(valor) FILTER (WHERE origem = \'PÚBLICO\') AS receitas_publicas,\n        SUM(valor) FILTER (WHERE origem = \'PRIVADO\') AS receitas_privadas,\n        TO_JSON(LIST(\n            STRUCT_PACK(fonte := fonte, origem := origem, valor := valor, qtd := qtd)\n            ORDER BY valor DESC\n        )) AS receitas\n    FROM receita_linhas\n    GROUP BY 1, 2\n),\ndespesa_linhas AS (\n    SELECT\n        dp.ano_eleicao,\n        dp.sq_candidato,\n        dp.ds_despesa,\n        dp.vr_pago,\n        ROW_NUMBER() OVER (\n            PARTITION BY dp.ano_eleicao, dp.sq_candidato\n            ORDER BY dp.vr_pago DESC NULLS LAST\n        ) AS rn\n    FROM public.despesas_pagas dp\n),\ndespesas AS (\n    SELECT\n        ano_eleicao,\n        sq_candidato,\n        SUM(vr_pago) AS total_despesas,\n        COUNT(*) AS qt_despesas,\n        TO_JSON(LIST(\n            STRUCT_PACK(despesa := ds_despesa, valor := vr_pago)\n            ORDER BY vr_pago DESC NULLS LAST\n        ) FILTER (WHERE rn <= 8)) AS despesas\n    FROM despesa_linhas\n    GROUP BY 1, 2\n),\nbens AS (\n    SELECT\n        bd.ano_eleicao,\n        bd.sq_candidato,\n        SUM(bd.vr_bem) AS total_bens,\n        TO_JSON(LIST(\n            STRUCT_PACK(\n                tipo := bd.ds_tipo_bem,\n                descricao := NULLIF(bd.ds_bem, \'#NULO#\'),\n                valor := bd.vr_bem\n            ) ORDER BY bd.vr_bem DESC NULLS LAST\n        )) AS bens\n    FROM public.bens_declarados bd\n    GROUP BY 1, 2\n)\nSELECT\n    c.id_pessoa_projeto,\n    c.ano_eleicao,\n    c.sq_candidato,\n    ca.nm_candidato,\n    c.nm_urna_candidato,\n    c.sg_partido AS partido,\n    c.ds_cargo AS cargo,\n    COALESCE(m.sg_uf, c.sg_ue) AS uf,\n    c.cd_municipio_tse AS municipio,\n    m.nm_municipio,\n    c.nr_turno_resultado AS turno,\n    c.ds_sit_tot_turno AS situacao,\n    c.qt_votos_totais AS votos,\n    COALESCE(r.total_receitas, 0) AS total_receitas,\n    COALESCE(r.receitas_publicas, 0) AS receitas_publicas,\n    COALESCE(r.receitas_privadas, 0) AS receitas_privadas,\n    COALESCE(r.receitas, \'[]\'::JSON) AS receitas,\n    d.total_despesas AS total_despesas,\n    COALESCE(d.qt_despesas, 0) AS qt_despesas,\n    COALESCE(d.despesas, \'[]\'::JSON) AS despesas,\n    COALESCE(b.total_bens, 0) AS patrimonio_declarado,\n    COALESCE(b.bens, \'[]\'::JSON) AS bens\nFROM public.candidatura c\nJOIN public.candidato ca\n    ON ca.id_pessoa_projeto = c.id_pessoa_projeto\nLEFT JOIN public.municipio m\n    ON m.cd_municipio_tse = c.cd_municipio_tse\nLEFT JOIN receitas r\n    USING (ano_eleicao, sq_candidato)\nLEFT JOIN despesas d\n    USING (ano_eleicao, sq_candidato)\nLEFT JOIN bens b\n    USING (ano_eleicao, sq_candidato);\n\n-- Q9: nuvens de palavras das descrições de despesas de propaganda.\n-- Banco BDR-TSE, schema public. Requer DS_ORIGEM_DESPESA carregada em\n-- despesas_pagas.ds_categoria_despesa. Nenhuma tabela auxiliar persistente.\n-- Escopo explícito: publicidade, produção de comunicação, internet,\n-- eventos/comícios e mobilização de rua. Não inferir propaganda de rubricas\n-- genéricas como pessoal ou serviços de terceiros.\n\nCREATE OR REPLACE VIEW public.vw_questao_9_nuvem_valor AS\nWITH propaganda AS (\n    SELECT ano_eleicao,sq_candidato,id_despesa,ds_despesa,vr_pago\n    FROM public.despesas_pagas\n    WHERE LOWER(strip_accents(TRIM(ds_categoria_despesa))) IN (\n        \'publicidade por carros de som\',\n        \'publicidade por adesivos\',\n        \'publicidade por jornais e revistas\',\n        \'publicidade por materiais impressos\',\n        \'producao de programas de radio, televisao ou video\',\n        \'producao de jingles, vinhetas e slogans\',\n        \'criacao e inclusao de paginas na internet\',\n        \'despesa com impulsionamento de conteudos\',\n        \'eventos de promocao da candidatura\',\n        \'comicios\',\n        \'atividades de militancia e mobilizacao de rua\'\n    )\n      AND ds_despesa IS NOT NULL AND vr_pago > 0\n), tokens AS (\n    -- Um termo conta uma vez por lançamento, mesmo se repetido na descrição.\n    SELECT DISTINCT p.ano_eleicao,p.sq_candidato,p.id_despesa,p.vr_pago,t.termo\n    FROM propaganda p,\n         UNNEST(regexp_split_to_array(\n             LOWER(strip_accents(p.ds_despesa)), \'[^a-z]+\'\n         )) AS t(termo)\n    WHERE LENGTH(t.termo) >= 3\n      AND t.termo NOT IN (\n        \'com\',\'para\',\'por\',\'dos\',\'das\',\'uma\',\'uns\',\'umas\',\'que\',\'como\',\'sem\',\n        \'sob\',\'sobre\',\'entre\',\'este\',\'esta\',\'esse\',\'essa\',\'estes\',\'estas\',\n        \'esses\',\'essas\',\'pelo\',\'pela\',\'pelos\',\'pelas\',\'seu\',\'sua\',\'seus\',\'suas\',\n        \'foi\',\'sao\',\'ser\',\'dia\',\'dias\',\'mes\',\'meses\',\'ano\',\'anos\',\n        \'servico\',\'servicos\',\'prestacao\',\'prestado\',\'prestados\',\'prestada\',\n        \'prestadas\',\'referente\',\'referentes\',\'conforme\',\'contrato\',\'contratos\',\n        \'contratacao\',\'pagamento\',\'pagamentos\',\'pago\',\'paga\',\'pagos\',\'pagas\',\n        \'nota\',\'notas\',\'fiscal\',\'fiscais\',\'nfe\',\'nfse\',\'recibo\',\'recibos\',\n        \'eleicao\',\'eleicoes\',\'eleitoral\',\'eleitorais\',\'campanha\',\'campanhas\',\n        \'candidato\',\'candidatos\',\'candidata\',\'candidatas\',\'candidatura\',\n        \'realizado\',\'realizada\',\'realizados\',\'realizadas\'\n      )\n), termos AS (\n    SELECT ano_eleicao,sq_candidato,termo,\n           SUM(vr_pago) AS valor_pago_associado,\n           COUNT(*) AS qt_lancamentos\n    FROM tokens\n    GROUP BY 1,2,3\n)\nSELECT t.ano_eleicao,t.sq_candidato,c.id_pessoa_projeto,\n       pessoa.nm_candidato,c.nm_urna_candidato,\n       COALESCE(m.sg_uf,c.sg_ue) AS uf,c.cd_municipio_tse,\n       c.ds_cargo,c.nr_partido,c.sg_partido,t.termo,\n       t.valor_pago_associado,t.qt_lancamentos,\n       t.valor_pago_associado AS peso\nFROM termos t\nJOIN public.candidatura c USING(ano_eleicao,sq_candidato)\nLEFT JOIN public.candidato pessoa USING(id_pessoa_projeto)\nLEFT JOIN public.municipio m USING(cd_municipio_tse);\n\n-- Mesmos termos, universo e métricas; só muda o peso visual.\n-- Frequência = lançamentos que contêm a palavra, não unidades adquiridas\n-- nem número garantido de compras/contratos (podem existir parcelas).\nCREATE OR REPLACE VIEW public.vw_questao_9_nuvem_frequencia AS\nSELECT * EXCLUDE(peso),qt_lancamentos AS peso\nFROM public.vw_questao_9_nuvem_valor;\n\n-- Exemplo (substitua o SQ pela candidatura desejada):\n-- SELECT termo,peso,valor_pago_associado,qt_lancamentos\n-- FROM public.vw_questao_9_nuvem_valor\n-- WHERE ano_eleicao=2024 AND sq_candidato=250002118287\n-- ORDER BY peso DESC,termo LIMIT 80;\n-- Troque o nome da view por vw_questao_9_nuvem_frequencia para frequência.\n-- Uma despesa pode conter várias palavras; somar pesos de palavras\n-- diferentes não equivale ao orçamento total. Filtre ano E SQ sempre.\n'

YEARS = (2004, 2006, 2008, 2010, 2012, 2014, 2016, 2018, 2020, 2022, 2024)
UFS = ("AC", "AL", "BA", "DF", "RO", "SP")
DB = "BDR-TSE"
CKAN = "https://dadosabertos.tse.jus.br/api/3/action"

SOURCES = (
    "consulta_cand", "consulta_cand_complementar", "votacao_candidato_munzona",
    "votacao_partido_munzona", "detalhe_votacao_munzona", "perfil_eleitorado",
    "bem_candidato", "prestacao_de_contas_eleitorais_candidatos",
)


def download(url, destination):
    request = urllib.request.Request(url, headers={"User-Agent": "Carga-TSE-MotherDuck/1.0"})
    digest = hashlib.sha256()
    total = 0
    with urllib.request.urlopen(request, timeout=180) as response, open(destination, "wb") as output:
        while True:
            block = response.read(1024 * 1024)
            if not block:
                break
            output.write(block)
            digest.update(block)
            total += len(block)
    if total == 0:
        raise RuntimeError(f"Arquivo vazio baixado: {url}")
    return {"url": url, "bytes": total, "sha256": digest.hexdigest()}


def acquire_sources(root):
    manifests = []
    for year in YEARS:
        for source in SOURCES:
            if source == "consulta_cand_complementar" and year < 2018:
                continue
            if source == "bem_candidato" and year == 2004:
                continue
            remote_source = "prestacao_contas" if source == "prestacao_de_contas_eleitorais_candidatos" and year < 2018 else source
            url = f"https://cdn.tse.jus.br/estatistica/sead/odsele/{remote_source}/{remote_source}_{year}.zip"
            path = root / f"{source}_{year}.zip"
            info = download(url, path)
            info.update({"year": year, "source": source})
            manifests.append(info)
            print(f"baixado {year} {source}: {info['bytes'] / 1e6:.1f} MB", flush=True)
    return manifests


STAGE_COLUMNS = {
    "stg_candidatura": "ano_eleicao cd_eleicao nr_turno cd_tipo_eleicao nm_tipo_eleicao sg_uf sg_ue nm_ue cd_cargo ds_cargo sq_candidato sq_candidato_tse nr_cpf_candidato nm_candidato nm_urna_candidato dt_nascimento ds_grau_instrucao ds_genero ds_cor_raca nr_partido sg_partido nm_partido ds_sit_tot_turno source_file nr_titulo_eleitoral_candidato nr_candidato",
    "stg_municipio": "cd_municipio_tse cd_municipio_ibge nm_municipio sg_uf source_file",
    "stg_votacao_partido": "ano_eleicao sg_uf cd_eleicao nr_turno cd_cargo cd_municipio_tse nr_partido sg_partido qt_votos_legenda qt_votos_nominais source_file",
    "stg_bem": "ano_eleicao sq_candidato nr_ordem_bem_candidato ds_tipo_bem_candidato ds_bem_candidato vr_bem_candidato source_file",
    "stg_receita": "ano_eleicao sq_candidato id_linha_origem ds_fonte_receita vr_receita tp_origem_recurso source_file",
    "stg_despesa": "ano_eleicao sq_candidato id_linha_origem ds_despesa ds_categoria_despesa vr_pago source_file",
    "stg_perfil": "ano_eleicao sg_uf cd_municipio_tse nr_zona ds_faixa_etaria ds_genero ds_estado_civil ds_grau_instrucao qt_eleitores_perfil source_file",
    "stg_votacao_candidato": "ano_eleicao sg_uf cd_eleicao nr_turno cd_cargo cd_municipio_tse sq_candidato qt_votos_nominais source_file",
    "stg_detalhe": "ano_eleicao sg_uf cd_eleicao nr_turno cd_cargo cd_municipio_tse nr_zona qt_aptos qt_comparecimento qt_abstencao source_file",
}

STAGE_FILES = {
    "stg_candidatura": "candidatura.csv",
    "stg_municipio": "municipio_correspondencia.csv",
    "stg_votacao_partido": "votacao_partido_munzona.csv",
    "stg_bem": "bem_candidato.csv",
    "stg_receita": "receita_candidato.csv",
    "stg_despesa": "despesa_candidato.csv",
    "stg_perfil": "perfil_eleitorado_municipio.csv",
    "stg_votacao_candidato": "votacao_candidato_munzona.csv",
    "stg_detalhe": "detalhe_votacao_munzona.csv",
}


def qident(value):
    return '"' + value.replace('"', '""') + '"'


def qliteral(value):
    return "'" + str(value).replace("'", "''") + "'"


def load_stage(con, name, columns, csv_path):
    definitions = ", ".join(f"{qident(column)} VARCHAR" for column in columns.split())
    con.execute(f"CREATE OR REPLACE TEMP TABLE {qident(name)} ({definitions})")
    con.execute(
        f"COPY {qident(name)} FROM {qliteral(csv_path)} "
        "(DELIMITER ';', HEADER FALSE, QUOTE '\"', ESCAPE '\"', NULL '')"
    )
    count = con.execute(f"SELECT COUNT(*) FROM {qident(name)}").fetchone()[0]
    print(f"staging local {name}: {count:,} linhas", flush=True)
    return count


def main():
    started = time.monotonic()
    zip_root = Path("/tmp/tse_full_2004_2024")
    stage_root = Path("/tmp/tse_motherduck_stage_2004_2024")
    shutil.rmtree(zip_root, ignore_errors=True)
    shutil.rmtree(stage_root, ignore_errors=True)
    zip_root.mkdir(parents=True)
    stage_root.mkdir(parents=True)

    source_manifest = acquire_sources(zip_root)
    namespace = {"__name__": "tse_normalizer", "__file__": "/tmp/normalizer.py"}
    exec(compile(NORMALIZER_SOURCE, "/tmp/normalizer.py", "exec"), namespace)
    sys.argv = ["normalizer.py", "--zip-dir", str(zip_root), "--output", str(stage_root)]
    namespace["main"]()

    normalizer_manifest = json.loads((stage_root / "manifest.json").read_text(encoding="utf-8"))
    con = duckdb.connect("md:")
    con.execute(f"CREATE DATABASE IF NOT EXISTS {qident(DB)}")
    con.execute(f"USE {qident(DB)}")

    counts = {}
    for table, columns in STAGE_COLUMNS.items():
        counts[table] = load_stage(con, table, columns, stage_root / STAGE_FILES[table])

    # Todas as transformacoes acontecem apos os CSVs passarem por CRC no parser.
    con.execute(MODEL_SQL)
    con.execute(VIEWS_SQL)

    expected_tables = {
        "municipio", "candidato", "partido", "candidatura", "bens_declarados",
        "receitas_campanha", "despesas_pagas", "perfil_eleitorado",
        "comparecimento_municipio", "votacao_partido", "votacao_candidato_municipio",
    }
    actual_tables = {
        row[0] for row in con.execute(
            "SELECT table_name FROM information_schema.tables "
            "WHERE table_schema='public' AND table_type='BASE TABLE'"
        ).fetchall()
    }
    if actual_tables != expected_tables:
        raise RuntimeError(f"Esquema final inesperado; tabelas: {sorted(actual_tables)}")
    expected_views = {
        "v_partidos_eleitos", "v_gasto_sucesso", "v_historico_candidato",
        "vw_questao_2_despesas",
        "vw_questao_9_nuvem_valor", "vw_questao_9_nuvem_frequencia",
    }
    actual_views = {
        row[0] for row in con.execute(
            "SELECT table_name FROM information_schema.views WHERE table_schema='public'"
        ).fetchall()
    }
    if actual_views != expected_views:
        raise RuntimeError(f"Views finais inesperadas: {sorted(actual_views)}")

    table_counts = {}
    for table in sorted(expected_tables):
        table_counts[table] = con.execute(
            f"SELECT COUNT(*) FROM public.{qident(table)}"
        ).fetchone()[0]
    q2_rows = con.execute("SELECT COUNT(*) FROM public.vw_questao_2_despesas").fetchone()[0]
    report = {
        "source": "Portal de Dados Abertos do TSE / API CKAN",
        "years": YEARS,
        "ufs": UFS,
        "source_archives": source_manifest,
        "normalizer": normalizer_manifest,
        "staging_rows": counts,
        "published_tables": table_counts,
        "published_views": sorted(actual_views),
        "q2_view_rows": q2_rows,
        "elapsed_seconds": round(time.monotonic() - started, 1),
    }
    print("MOTHERDUCK_LOAD_REPORT=" + json.dumps(report, ensure_ascii=False), flush=True)
    con.close()
    shutil.rmtree(zip_root, ignore_errors=True)
    shutil.rmtree(stage_root, ignore_errors=True)


if __name__ == "__main__":
    main()
